SELECT CAST('project' AS TEXT) AS kind, project_id AS record_id, workspace_id AS workspace_id, board_id AS board_id, name AS business_name, CAST(NULL AS TEXT) AS business_version, CAST(NULL AS TEXT) AS source_hash, payload AS payload, router_time AS router_time, time_basis AS time_basis, origin_installation AS origin_installation, origin_machine AS origin_machine, import_digest AS import_digest FROM project_directory WHERE board_id = ? ORDER BY project_id;
